1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.service.ClinicService;
13	
14	import java.time.LocalDate;
15	import java.time.Period;
16	import java.time.temporal.ChronoUnit;
17	import java.util.Collection;
18	import java.util.List;
19	import java.util.Map;
20	import java.util.Objects;
21	
22	/**
23	 * Maps Owner &amp; OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public abstract class OwnerMapper {
27	
28	    /**
29	     * A create is flagged with {@code bulkSignupWarning=true} once more than this many owners have
30	     * already been created on the same registration date.
31	     */
32	    private static final int BULK_SIGNUP_THRESHOLD = 80;
33	
34	    @Autowired
35	    protected ClinicService clinicService;
36	
37	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
38	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
39	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
40	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
41	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
42	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
43	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
44	    @Mapping(target = "locality", expression = "java(locality(owner))")
45	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
46	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
47	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
48	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
49	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
50	    public abstract OwnerDto toOwnerDto(Owner owner);
51	
52	    /**
53	     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
54	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
55	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
56	     * the registration date (against which the age is measured) is absent.
57	     */
58	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
59	        LocalDate birthDate = owner.getBirthDate();
60	        LocalDate registrationDate = owner.getRegistrationDate();
61	        if (birthDate == null || registrationDate == null) {
62	            return null;
63	        }
64	        int age = Period.between(birthDate, registrationDate).getYears();
65	        if (age < 18) {
66	            return OwnerDto.AgeBandEnum.MINOR;
67	        }
68	        if (age < 65) {
69	            return OwnerDto.AgeBandEnum.ADULT;
70	        }
71	        return OwnerDto.AgeBandEnum.SENIOR;
72	    }
73	
74	    /**
75	     * The country calling codes (without the leading {@code '+'}) the display formatter recognises,
76	     * longest first so the correct code is matched before a shorter prefix of it. Australia
77	     * ({@code +61}) and the North American Numbering Plan ({@code +1}) mirror the codes the create
78	     * endpoint normalizes against.
79	     */
80	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
81	
82	    /**
83	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
84	     * humans as the country code, a space, then the national digits grouped in threes (e.g.
85	     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
86	     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
87	     */
88	    protected String telephoneDisplay(Owner owner) {
89	        String telephone = owner.getTelephone();
90	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
91	            return telephone;
92	        }
93	        String digits = telephone.substring(1);
94	        String countryCode = KNOWN_COUNTRY_CODES.stream()
95	            .filter(digits::startsWith)
96	            .findFirst()
97	            .orElse("");
98	        String national = digits.substring(countryCode.length());
99	        StringBuilder grouped = new StringBuilder();
100	        for (int i = 0; i < national.length(); i++) {
101	            if (i > 0 && i % 3 == 0) {
102	                grouped.append(' ');
103	            }
104	            grouped.append(national.charAt(i));
105	        }
106	        return "+" + countryCode + " " + grouped;
107	    }
108	
109	    /**
110	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key:
111	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A {@code null}
112	     * email or householdId contributes an empty segment.
113	     */
114	    protected String identityKey(Owner owner) {
115	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
116	        String email = owner.getEmail() == null ? "" : owner.getEmail();
117	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
118	        return telephone + "|" + email + "|" + householdId;
119	    }
120	
121	    /**
122	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
123	     * present, otherwise {@code PHONE}.
124	     */
125	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
126	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
127	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
128	    }
129	
130	    /**
131	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
132	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
133	     */
134	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
135	        "NSW", new int[] {2000, 2099},
136	        "VIC", new int[] {3000, 3099},
137	        "QLD", new int[] {4000, 4099});
138	
139	    /**
140	     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
141	     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
142	     * moves in lockstep with the identity assigned on create. When no customer code has been
143	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
144	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
145	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
146	     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
147	     */
148	    protected String locality(Owner owner) {
149	        String customerCode = owner.getCustomerCode();
150	        if (customerCode != null) {
151	            int dash = customerCode.indexOf('-');
152	            if (dash > 0) {
153	                return customerCode.substring(0, dash);
154	            }
155	        }
156	        String fromPostcode = regionFromPostcode(owner.getPostcode());
157	        if (fromPostcode != null) {
158	            return fromPostcode;
159	        }
160	        String city = owner.getCity();
161	        if (city == null) {
162	            return "UNKNOWN";
163	        }
164	        return switch (city) {
165	            case "Sydney" -> "NSW";
166	            case "Melbourne" -> "VIC";
167	            case "Brisbane" -> "QLD";
168	            default -> "UNKNOWN";
169	        };
170	    }
171	
172	    /**
173	     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
174	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
175	     */
176	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
177	        "NSW", "Australia/Sydney",
178	        "VIC", "Australia/Melbourne",
179	        "QLD", "Australia/Brisbane");
180	
181	    /**
182	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
183	     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
184	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
185	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
186	     */
187	    protected String timezone(Owner owner) {
188	        return REGION_TIMEZONE.get(locality(owner));
189	    }
190	
191	    /**
192	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
193	     * the postcode is absent, not 4 digits, or in no known range.
194	     */
195	    private String regionFromPostcode(String postcode) {
196	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
197	            return null;
198	        }
199	        int value = Integer.parseInt(postcode);
200	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
201	            int[] range = entry.getValue();
202	            if (value >= range[0] && value <= range[1]) {
203	                return entry.getKey();
204	            }
205	        }
206	        return null;
207	    }
208	
209	    /**
210	     * The minimum household size (counting the owner itself) that earns household membership
211	     * points.
212	     */
213	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
214	
215	    /**
216	     * An owner must have been registered for strictly more than this many days to earn the
217	     * tenure membership points. A newly created owner has zero tenure and so never clears this
218	     * threshold.
219	     */
220	    private static final int TENURE_POINTS_DAYS = 365;
221	
222	    /**
223	     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
224	     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
225	     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
226	     * tenure exceeds {@value #TENURE_POINTS_DAYS} days.
227	     */
228	    protected Integer membershipPoints(Owner owner) {
229	        int points = 0;
230	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
231	        if (hasEmail) {
232	            points += 2;
233	        }
234	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
235	        if (noNamesakes) {
236	            points += 1;
237	        }
238	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
239	            points += 2;
240	        }
241	        if (tenureDays(owner) > TENURE_POINTS_DAYS) {
242	            points += 3;
243	        }
244	        return points;
245	    }
246	
247	    /**
248	     * Derives the owner's membership level from their {@link #membershipPoints(Owner) membership
249	     * points}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more.
250	     */
251	    protected Integer membershipLevel(Owner owner) {
252	        int points = membershipPoints(owner);
253	        if (points <= 1) {
254	            return 1;
255	        }
256	        if (points <= 3) {
257	            return 2;
258	        }
259	        if (points <= 5) {
260	            return 3;
261	        }
262	        return 4;
263	    }
264	
265	    /**
266	     * The number of owners in this owner's household — the count of owners (including this one)
267	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
268	     */
269	    private long householdSize(Owner owner) {
270	        String householdId = owner.getHouseholdId();
271	        if (householdId == null) {
272	            return 0;
273	        }
274	        return this.clinicService.findAllOwners().stream()
275	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
276	            .count();
277	    }
278	
279	    /**
280	     * The owner's tenure in whole days: the number of days from their {@code registrationDate} up to
281	     * the current date. Returns 0 when no registration date is present, so an owner without a
282	     * registration date is treated as having no tenure.
283	     */
284	    private long tenureDays(Owner owner) {
285	        LocalDate registrationDate = owner.getRegistrationDate();
286	        if (registrationDate == null) {
287	            return 0;
288	        }
289	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
290	    }
291	
292	    /**
293	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
294	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
295	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
296	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
297	     * owner has no registration date.
298	     */
299	    protected Boolean bulkSignupWarning(Owner owner) {
300	        LocalDate registrationDate = owner.getRegistrationDate();
301	        if (registrationDate == null) {
302	            return false;
303	        }
304	        long othersOnDay = this.clinicService.findAllOwners().stream()
305	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
306	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
307	            .count();
308	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
309	    }
310	
311	    /**
312	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the digits
313	     * contained in the owner's {@code customerCode}. Non-digit characters are ignored. Returns
314	     * {@code null} when no customer code has been assigned.
315	     */
316	    protected Integer checkDigit(Owner owner) {
317	        String customerCode = owner.getCustomerCode();
318	        if (customerCode == null) {
319	            return null;
320	        }
321	        int sum = 0;
322	        boolean dbl = true;
323	        for (int i = customerCode.length() - 1; i >= 0; i--) {
324	            char c = customerCode.charAt(i);
325	            if (c < '0' || c > '9') {
326	                continue;
327	            }
328	            int d = c - '0';
329	            if (dbl) {
330	                d *= 2;
331	                if (d > 9) {
332	                    d -= 9;
333	                }
334	            }
335	            sum += d;
336	            dbl = !dbl;
337	        }
338	        return (10 - (sum % 10)) % 10;
339	    }
340	
341	    /**
342	     * Derives the owner's {@code salutation}: the owner's {@code title} and {@code lastName}
343	     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
344	     * title was supplied (a {@code null} or blank title).
345	     */
346	    protected String salutation(Owner owner) {
347	        String title = owner.getTitle();
348	        String lastName = owner.getLastName();
349	        if (title == null || title.isBlank()) {
350	            return lastName;
351	        }
352	        return title + " " + lastName;
353	    }
354	
355	    public abstract Owner toOwner(OwnerDto ownerDto);
356	
357	    @Mapping(target = "id", ignore = true)
358	    @Mapping(target = "pets", ignore = true)
359	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
360	
361	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
362	
363	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
364	
365	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
366	        OwnerPageDto ownerPageDto = new OwnerPageDto();
367	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
368	        ownerPageDto.setPage(ownerPage.getNumber());
369	        ownerPageDto.setSize(ownerPage.getSize());
370	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
371	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
372	        return ownerPageDto;
373	    }
374	}
